package com.bidx.service;import com.bidx.model.*;import com.bidx.repository.*;import com.bidx.util.*;import java.time.*;import java.math.*;import java.util.*;import java.util.stream.*;
public class AuctionService {private final AuctionRepository auctions=new AuctionRepository();private final BidRepository bids=new BidRepository();public List<Auction> browse(String q,String category,String status,String sort){reconcile();Stream<Auction>s=auctions.all().stream();if(q!=null&&!q.isBlank())s=s.filter(a->a.title.toLowerCase().contains(q.toLowerCase()));if(category!=null&&!category.isBlank())s=s.filter(a->a.category.equalsIgnoreCase(category));if(status!=null&&!status.isBlank())s=s.filter(a->a.status.name().equals(status));Comparator<Auction> c=switch(sort==null?"newest":sort){case "ending"->Comparator.comparing(a->a.endAt);case "low"->Comparator.comparing(a->a.currentHighestBid);case "high"->Comparator.comparing((Auction a)->a.currentHighestBid).reversed();default->Comparator.comparing((Auction a)->a.createdAt).reversed();};return s.sorted(c).toList();}public Auction find(String id){reconcile();return auctions.find(id);}public synchronized void create(Auction a,String seller){if(a.title==null||a.title.isBlank()||a.description==null||a.description.isBlank()||a.startingPrice==null||a.startingPrice.signum()<0||a.minimumIncrement==null||a.minimumIncrement.signum()<=0||a.startAt==null||a.endAt==null||!a.endAt.isAfter(a.startAt))throw new IllegalArgumentException("Please complete all fields and use a valid future auction period.");a.id=IdGenerator.next("AUC");a.sellerId=seller;a.currentHighestBid=a.startingPrice;a.status=statusFor(a);a.createdAt=LocalDateTime.now();a.updatedAt=a.createdAt;auctions.insert(a);}public AuctionStatus statusFor(Auction a){if(a.status==AuctionStatus.CANCELLED)return a.status;LocalDateTime n=LocalDateTime.now();if(!n.isBefore(a.endAt)){a.winnerId=a.highestBidderId;return a.highestBidderId==null||a.highestBidderId.isBlank()?AuctionStatus.CLOSED:AuctionStatus.COMPLETED;}if(n.isBefore(a.startAt))return AuctionStatus.UPCOMING;return java.time.Duration.between(n,a.endAt).toMinutes()<30?AuctionStatus.ENDING_SOON:AuctionStatus.ACTIVE;}public synchronized void reconcile(){for(Auction a:auctions.all()){AuctionStatus before=a.status;AuctionStatus now=statusFor(a);if(now!=before){a.status=now;a.updatedAt=LocalDateTime.now();auctions.update(a);}}}public long bidCount(String id){return bids.forAuction(id).size();}public List<Auction> mine(String id){reconcile();return auctions.all().stream().filter(a->a.sellerId.equals(id)).toList();}}
